 */
scwin.btn_CheckValues_onclick = function(e){
    try {
        CheckValues('__self.form',(String(((dma_pageContext.get("bndMktactTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("bndMktactTpCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("bndMktactTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("bndMktactTpCd") ?? "")))))

